// Receives the "registration.paid" payload from events.theaugustdispatch.com
// (docs/n8n-webhooks.md in the site repo), then builds the "seat confirmed"
// email and a calendar invite covering all four Saturdays.
const SECRET = 'SET_IN_N8N';
const input = $input.first().json;
if ((input.headers || {})['x-webhook-secret'] !== SECRET) return [];

const p = input.body || {};
if (p.event_type !== 'registration.paid' || !p.registration) return [];

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const r = p.registration, ev = p.event, ch = p.channels || {};

// Calendar invite. Accra is UTC all year, so local times are written as UTC.
const icsText = (s) => String(s ?? '').replace(/\\/g, '\\\\').replace(/;/g, '\;').replace(/,/g, '\\,').replace(/\n/g, '\\n');
const stamp = (date, time) => `${date.replace(/-/g, '')}T${time.replace(':', '')}00Z`;
const now = new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d+/, '');
const vevents = ev.dates.map((date, i) => [
  'BEGIN:VEVENT',
  `UID:tabs-1-0-${date}-${r.id}@events.theaugustdispatch.com`,
  `DTSTAMP:${now}`,
  `DTSTART:${stamp(date, ev.start_time)}`,
  `DTEND:${stamp(date, ev.end_time)}`,
  `SUMMARY:${icsText(`${ev.name}: Saturday ${i + 1} of ${ev.dates.length}`)}`,
  `LOCATION:${icsText(`${ev.venue_name}, ${ev.venue_address}`)}`,
  `DESCRIPTION:${icsText(`Bring: ${(ev.what_to_bring || []).join('; ')}.\nDirections: ${ev.venue_maps_url}\nQuestions: WhatsApp ${ev.contact_whatsapp}`)}`,
  `URL:${ev.url}`,
  'END:VEVENT',
].join('\r\n'));
const ics = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//The AI Build Shop//TABS 1.0//EN', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH', ...vevents, 'END:VCALENDAR'].join('\r\n') + '\r\n';

const bring = (ev.what_to_bring || []).map((b) => `<li style="margin:0 0 6px">${esc(b)}</li>`).join('');

const html = `<div style="background:#EEF2F6;padding:24px 12px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:#0D1B2A;border-radius:16px;overflow:hidden">
  <tr><td style="padding:14px 32px;border-bottom:3px solid #F5C518;font:700 13px 'Courier New',monospace;letter-spacing:1.5px;color:#F5C518">${esc(ev.edition)}</td></tr>
  <tr><td style="padding:32px 32px 0">
    <div style="font:800 30px/1.15 Arial,sans-serif;color:#ffffff">Your seat is confirmed, ${esc(r.first_name)}.</div>
    <div style="margin-top:14px;font:16px/1.6 Arial,sans-serif;color:#EEF2F6">We have received your payment. See you at ${esc(ev.name)}.</div>
  </td></tr>
  <tr><td style="padding:24px 32px 0"><div style="border:1px solid #F5C518;border-radius:12px;padding:20px;background:#13263A">
    <div style="font:700 11px 'Courier New',monospace;letter-spacing:2px;text-transform:uppercase;color:#F5C518">When</div>
    <div style="margin:4px 0 14px;font:700 17px/1.4 Arial,sans-serif;color:#ffffff">${esc(ev.dates_label)}, ${esc(ev.start_time)} to ${esc(ev.end_time)}</div>
    <div style="font:700 11px 'Courier New',monospace;letter-spacing:2px;text-transform:uppercase;color:#F5C518">Where</div>
    <div style="margin-top:4px;font:700 17px/1.4 Arial,sans-serif;color:#ffffff">${esc(ev.venue_name)}, ${esc(ev.venue_address)}</div>
    <div style="margin-top:8px"><a href="${esc(ev.venue_maps_url)}" style="font:15px Arial,sans-serif;color:#F5C518">Open in Google Maps</a></div>
  </div></td></tr>
  <tr><td style="padding:22px 32px 0;font:16px/1.6 Arial,sans-serif;color:#EEF2F6">The calendar invite attached to this email adds all four Saturdays to your calendar.</td></tr>
  <tr><td style="padding:22px 32px 0;font:800 19px Arial,sans-serif;color:#ffffff">What to bring</td></tr>
  <tr><td style="padding:8px 32px 0"><ul style="margin:0;padding-left:20px;font:16px/1.5 Arial,sans-serif;color:#EEF2F6">${bring}</ul></td></tr>
  <tr><td style="padding:18px 32px 0;font:16px/1.6 Arial,sans-serif;color:#EEF2F6">${esc(ev.setup_checklist_note)}</td></tr>
  <tr><td style="padding:22px 32px 32px;font:14px/1.6 Arial,sans-serif;color:#B9C5D3">Questions? WhatsApp ${esc(ev.contact_whatsapp)} or email <a href="mailto:${esc(ev.contact_email)}" style="color:#F5C518">${esc(ev.contact_email)}</a>.</td></tr>
</table></div>`;

return [{
  json: {
    to: ch.email?.to || r.email,
    emailEnabled: ch.email?.enabled !== false,
    whatsappEnabled: ch.whatsapp?.enabled === true,
    whatsappTo: ch.whatsapp?.to || r.whatsapp,
    subject: `Your seat is confirmed: ${ev.name}`,
    replyTo: ev.contact_email,
    html,
    registrationId: r.id,
    firstName: r.first_name,
  },
  binary: {
    invite: await this.helpers.prepareBinaryData(Buffer.from(ics, 'utf8'), 'the-ai-build-shop.ics', 'text/calendar'),
  },
}];
